"""Channel configuration for Mantle projects.

Mantle declares its input channels in ``integrations.yml`` under a ``channels:``
key, alongside the other integrations (LLM, MCP servers). This replaces the
CALM v1 ``credentials.yml`` mechanism, which remains in use for v1 projects.

Each entry maps a channel name (matching the ``BUILTIN_CHANNELS`` registry) to
its configuration. A bare ``{ enabled: true }`` enables the channel with its
defaults; a full config dict enables it with those keyword arguments;
``enabled: false`` disables a channel without deleting its configuration. The
parsed result matches the shape consumed by :class:`CredentialsConfig`.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Mapping, Optional, Union

import structlog
from pydantic import BaseModel, ConfigDict, ValidationError

from rasa.core.a2a_server.config import A2A_SERVER_KEY
from rasa.core.constants import RASA_A2A_INPUT_CHANNEL
from rasa.shared.exceptions import RasaException
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE
from rasa.shared.utils.yaml import read_yaml_file

structlogger = structlog.get_logger()

CHANNELS_KEY = "channels"
ENABLED_KEY = "enabled"


class ChannelConfig(BaseModel):
    """A single channel entry from the ``channels:`` block of integrations.yml."""

    model_config = ConfigDict(frozen=True, extra="allow")

    enabled: bool = True

    def channel_kwargs(self) -> Dict[str, Any]:
        """Return the channel's keyword arguments, without the ``enabled`` flag."""
        return self.model_dump(exclude={ENABLED_KEY})


def parse_channels(
    raw_channels: Mapping[str, Union[Mapping[str, Any], None]],
) -> Dict[str, Dict[str, Any]]:
    """Convert a raw ``channels:`` mapping into the credentials-config shape.

    Args:
        raw_channels: The ``channels:`` mapping as read from integrations.yml,
            keyed by channel name. Each value is a config mapping, ``{ enabled:
            <bool> }`` shorthand, or ``None`` (enabled with defaults).

    Returns:
        A mapping of enabled channel names to their keyword arguments, with the
        ``enabled`` flag stripped. Disabled channels are omitted.

    Raises:
        RasaException: If an entry is neither a mapping nor ``None``, if its
            ``enabled`` value is not a boolean, or if it names the A2A protocol,
            which is served from the top-level ``a2a_server`` block and is not
            an input channel.
    """
    parsed: Dict[str, Dict[str, Any]] = {}
    for name, raw_config in raw_channels.items():
        if name == RASA_A2A_INPUT_CHANNEL:
            raise RasaException(
                f"'{CHANNELS_KEY}.{RASA_A2A_INPUT_CHANNEL}' in "
                f"'{MANTLE_INTEGRATIONS_FILE}' is not an input channel. Configure the "
                f"inbound A2A server in a top-level '{A2A_SERVER_KEY}' block instead."
            )
        if raw_config is None:
            parsed[name] = {}
            continue
        if not isinstance(raw_config, Mapping):
            raise RasaException(
                f"Channel '{name}' in '{MANTLE_INTEGRATIONS_FILE}' must be a mapping "
                f"or empty, but got '{type(raw_config).__name__}'."
            )
        try:
            channel = ChannelConfig.model_validate(dict(raw_config))
        except ValidationError as error:
            raise RasaException(
                f"Invalid configuration for channel '{name}' in "
                f"'{MANTLE_INTEGRATIONS_FILE}': {error}"
            ) from error
        if not channel.enabled:
            continue
        parsed[name] = channel.channel_kwargs()
    return parsed


def load_integration_channels(
    project_root: Union[str, Path],
) -> Optional[Dict[str, Dict[str, Any]]]:
    """Load channel configuration from a project's ``integrations.yml``.

    Environment variables (``${VAR}``) inside the ``channels:`` block are
    expanded at read time, consistent with ``credentials.yml``.

    Args:
        project_root: Directory expected to contain ``integrations.yml``.

    Returns:
        The parsed channels mapping, or ``None`` if the file does not exist or
        does not declare a ``channels:`` block. For Mantle the caller treats
        ``None`` as "no channels" — it never falls back to ``credentials.yml``.
    """
    integration_file = Path(project_root) / MANTLE_INTEGRATIONS_FILE
    if not integration_file.is_file():
        return None

    raw = read_yaml_file(integration_file, expand_env_vars=True)
    if not isinstance(raw, Mapping):
        return None

    raw_channels = raw.get(CHANNELS_KEY)
    if raw_channels is None:
        return None
    if not isinstance(raw_channels, Mapping):
        raise RasaException(
            f"'{CHANNELS_KEY}' in '{MANTLE_INTEGRATIONS_FILE}' must be a mapping of "
            f"channel names to their configuration."
        )

    channels = parse_channels(raw_channels)
    structlogger.debug(
        "mantle.channels.loaded_from_integration",
        channel_count=len(channels),
        channel_names=sorted(channels),
    )
    return channels
